import tempfile
import os
from pylint.lint.run import Run

def test_short_and_long_verbose_work_without_argument():
    with tempfile.NamedTemporaryFile('w', suffix='.py', delete=False) as f:
        f.write('print("hello")\n')
        fname = f.name
    try:
        # Test short option -v
        try:
            Run([fname, '-v'], exit=False)
        except SystemExit as e:
            assert e.code == 0, f"pylint -v exited with code {e.code}"
        # Test long option --verbose
        try:
            Run([fname, '--verbose'], exit=False)
        except SystemExit as e:
            assert e.code == 0, f"pylint --verbose exited with code {e.code}"
    finally:
        os.unlink(fname)
